#include <iostream>
#include <vector>
#include <unordered_map>
#include <cmath>
#include <string>
#include <sstream>

using namespace std;

vector<int> stringToIntArray(const string& s) {
    vector<int> result;
    stringstream ss(s);
    int number;
    while (ss >> number) {
        result.push_back(number);
    }
    return result;
}

class Cutting {
public:
    bool isSubArrayBalanced(const vector<int>& arr, int index) {
        int evenCount = 0;
        int oddCount = 0;
        for (int i = 0; i <= index; i++) {
            if (arr[i] % 2 == 0)
                evenCount++;
            else
                oddCount++;
        }
        return evenCount == oddCount;
    }

    int findMinimumCostIndex(const vector<int>& arr, int coins, unordered_map<int, bool>& usedCuts) {
        int minIndex = -1;
        int minCost = coins + 1;
        for (int i = 1; i < (int)arr.size() - 1; i++) {
            int cost = abs(arr[i] - arr[i + 1]);
            if (cost < minCost && isSubArrayBalanced(arr, i) && usedCuts.find(i) == usedCuts.end()) {
                minCost = cost;
                minIndex = i;
            }
        }
        return minIndex;
    }

    int calculateMaxCuts(int total, int budget, const vector<int>& arr) {
        int remainingCoins = budget;
        int cutsCount = 0;
        unordered_map<int, bool> usedIndices;
        while (remainingCoins > 0) {
            int index = findMinimumCostIndex(arr, remainingCoins, usedIndices);
            if (index >= 0) {
                usedIndices[index] = true;
                int cost = abs(arr[index] - arr[index + 1]);
                remainingCoins -= cost;
                cutsCount++;
            } else {
                break;
            }
        }
        return cutsCount;
    }
};

int main() {
    string line1, line2;
    getline(cin, line1);
    getline(cin, line2);
    vector<int> nbArr = stringToIntArray(line1);
    vector<int> aArr = stringToIntArray(line2);
    int n = nbArr[0];
    int b = nbArr[1];
    Cutting c;
    int maxCuts = c.calculateMaxCuts(n, b, aArr);
    cout << maxCuts << "\n";
    return 0;
}

